window.InterviewContent.materials.push(
{"id":"architecture-fsd:module","topic":"architecture-fsd","tab":"junior","ordinal":1,"targetLevel":"junior","angles":[],"kind":"question","title":"Зачем делить приложение на модули?","shortAnswer":"Чтобы локализовать ответственность и уменьшить связанность изменений.","explanation":"Файл сам по себе ещё не граница: важны публичный контракт и скрытые детали. Разделение по длине кода не гарантирует cohesion.","assessment":{"basic":"Называет ответственность.","confident":"Выделяет контракт. Чтобы локализовать ответственность и уменьшить связанность изменений.","deep":"Общую ответственность и реальную связанность; возможно, граница проведена не по причинам изменения."},"followUps":[{"kind":"support","question":"Что должна скрывать граница модуля от потребителя?","expected":"Внутренние детали, не входящие в стабильный контракт."},{"kind":"transfer","question":"Два модуля всегда меняются вместе. Что исследуете?","expected":"Общую ответственность и реальную связанность; возможно, граница проведена не по причинам изменения."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Разделите код каталога на модули и объясните, какие изменения локализует каждая граница."},
{"id":"architecture-fsd:dependency","topic":"architecture-fsd","tab":"junior","ordinal":2,"targetLevel":"junior","angles":[],"kind":"question","title":"Что означает направление зависимости?","shortAnswer":"Модуль знает API другого модуля и зависит от его изменения.","explanation":"Импорт — видимая зависимость, но общие данные и протоколы тоже связывают код. Циклы усложняют инициализацию и изменения.","assessment":{"basic":"Читает import graph.","confident":"Находит скрытую связь. Модуль знает API другого модуля и зависит от его изменения.","deep":"Нет; контракт стал неявным, его всё равно нужно учитывать и проверять."},"followUps":[{"kind":"support","question":"Создаёт ли импорт зависимость от чужого контракта?","expected":"Да; изменение экспортируемого API может затронуть потребителя."},{"kind":"transfer","question":"Импорт заменили строковым именем сервиса. Исчезла ли зависимость?","expected":"Нет; контракт стал неявным, его всё равно нужно учитывать и проверять."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"В примере тарифы предлагается связать со страницей заказа. Проследите граф и оцените новую зависимость.","questionCode":"pages/order → pricing → tariffs\nПредлагаемая новая связь: tariffs → pages/order","questionCodeLanguage":"text"},
{"id":"architecture-fsd:separation","topic":"architecture-fsd","tab":"junior","ordinal":3,"targetLevel":"junior","angles":[],"kind":"question","title":"Почему UI и работа с API часто разделяются?","shortAnswer":"У них разные причины изменения и разные границы тестирования.","explanation":"Разделение не требует слоя ради каждого вызова. Полезна граница, которая скрывает транспорт и преобразует внешний контракт.","assessment":{"basic":"Различает UI/transport.","confident":"Выделяет data boundary. У них разные причины изменения и разные границы тестирования.","deep":"Выделить независимый контракт правила и адаптеры окружения, не переносить в него детали DOM."},"followUps":[{"kind":"support","question":"Почему сетевой запрос труднее тестировать вместе с отрисовкой?","expected":"Он добавляет внешние эффекты и другой источник ошибок."},{"kind":"transfer","question":"Доменное правило используется в CLI и UI. Как измените границу?","expected":"Выделить независимый контракт правила и адаптеры окружения, не переносить в него детали DOM."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Компонент получает API-данные, считает скидку и рисует форму. Предложите проверяемые границы ответственности."},
{"id":"architecture-fsd:fsd-layers","topic":"architecture-fsd","tab":"junior","ordinal":4,"targetLevel":"junior","angles":[],"kind":"question","title":"Какие слои используются в FSD?","shortAnswer":"App, Pages, Widgets, Features, Entities и Shared; Processes устарел.","explanation":"Слои отражают ответственность и направление зависимостей. Не каждый проект обязан заполнять все слои.","assessment":{"basic":"Называет основные слои.","confident":"Понимает нижнее направление. App, Pages, Widgets, Features, Entities и Shared; Processes устарел.","deep":"Оценить фактические сценарии и мигрировать осмысленно; учитывать устаревание слоя без механического переименования."},"followUps":[{"kind":"support","question":"Что определяет слой: название папки или ответственность?","expected":"Ответственность и допустимое направление зависимостей."},{"kind":"transfer","question":"В проекте есть Processes из старой версии методики. Как действовать?","expected":"Оценить фактические сценарии и мигрировать осмысленно; учитывать устаревание слоя без механического переименования."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Распределите инициализацию, страницу, действие пользователя и базовую кнопку по слоям FSD."},
{"id":"architecture-fsd:fsd-slice","topic":"architecture-fsd","tab":"junior","ordinal":5,"targetLevel":"junior","angles":[],"kind":"question","title":"Что такое slice в FSD?","shortAnswer":"Содержательный модуль внутри слоя, например сущность или пользовательская возможность.","explanation":"Slices разделяются по смыслу, segments — по техническому назначению. В Shared и App обычно нет такого бизнес-деления на slices.","assessment":{"basic":"Различает slice/segment.","confident":"Даёт доменный пример. Содержательный модуль внутри слоя, например сущность или пользовательская возможность.","deep":"По различающимся владельцам и причинам изменения, сохраняя ясные публичные контракты."},"followUps":[{"kind":"support","question":"Что объединяет содержимое slice?","expected":"Одна смысловая область, а не один тип файлов."},{"kind":"transfer","question":"Slice разросся до нескольких независимых сценариев. Когда разделять?","expected":"По различающимся владельцам и причинам изменения, сохраняя ясные публичные контракты."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"По структуре add-to-cart и sign-in объясните различие slice и segment.","questionCode":"features/\n  add-to-cart/\n    ui/\n    model/\n    api/\n  sign-in/\n    ui/\n    model/","questionCodeLanguage":"text"},
{"id":"architecture-fsd:public-api","topic":"architecture-fsd","tab":"junior","ordinal":6,"targetLevel":"junior","angles":[],"kind":"question","title":"Для чего модулю public API?","shortAnswer":"Чтобы потребители зависели от стабильного входа, а не внутренней структуры.","explanation":"Прямой импорт внутреннего файла делает рефакторинг breaking change. Экспортировать следует нужное, не все внутренности подряд.","assessment":{"basic":"Использует единый вход.","confident":"Скрывает детали. Чтобы потребители зависели от стабильного входа, а не внутренней структуры.","deep":"Узкий явный контракт и владелец; проверить, не лучше ли перенести композицию, избегая бесконтрольного экспорта всего."},"followUps":[{"kind":"support","question":"Чем опасен импорт внутреннего файла чужого slice?","expected":"Связывает потребителя с деталью реализации."},{"kind":"transfer","question":"Нужно срочно открыть внутреннюю функцию одному потребителю. Как оформить?","expected":"Узкий явный контракт и владелец; проверить, не лучше ли перенести композицию, избегая бесконтрольного экспорта всего."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Потребитель импортирует внутреннюю функцию чужого slice. Предложите устойчивую границу API."},
{"id":"architecture-fsd:shared","topic":"architecture-fsd","tab":"junior","ordinal":7,"targetLevel":"junior","angles":[],"kind":"question","title":"Что помещать в Shared?","shortAnswer":"Независимую от конкретных бизнес-сценариев инфраструктуру и переиспользуемые основы.","explanation":"Shared не должен становиться свалкой. Бизнес-правило заказа не становится общим только потому, что используется дважды.","assessment":{"basic":"Отличает техническое от доменного.","confident":"Не выносит по повторению автоматически. Независимую от конкретных бизнес-сценариев инфраструктуру и переиспользуемые основы.","deep":"Не по внешнему сходству; проверить общий смысл и устойчивый контракт."},"followUps":[{"kind":"support","question":"Должен ли Shared знать правила оформления заказа?","expected":"Нет; это бизнес-сценарий другого владельца."},{"kind":"transfer","question":"Две функции в Shared используют только одинаковый цвет, но разное поведение. Объединять ли их?","expected":"Не по внешнему сходству; проверить общий смысл и устойчивый контракт."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Разместите HTTP-клиент, базовую кнопку и правило скидки. Обоснуйте границу Shared."},
{"id":"architecture-fsd:entity","topic":"architecture-fsd","tab":"junior","ordinal":8,"targetLevel":"junior","angles":[],"kind":"question","title":"Что считать Entity?","shortAnswer":"Значимую для предметной области сущность и связанную с ней модель/представление.","explanation":"Не каждый ответ API требует отдельного entity-slice. Выделение полезно при устойчивом доменном смысле.","assessment":{"basic":"Даёт доменный пример.","confident":"Различает DTO/entity. Значимую для предметной области сущность и связанную с ней модель/представление.","deep":"Разные bounded contexts и модели; одинаковое имя не требует одного универсального slice."},"followUps":[{"kind":"support","question":"Чем сущность отличается от кнопки, показывающей её?","expected":"Сущность отражает предметную модель, кнопка — лишь возможное представление."},{"kind":"transfer","question":"Один и тот же User имеет разные правила в админке и магазине. Что исследуете?","expected":"Разные bounded contexts и модели; одинаковое имя не требует одного универсального slice."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Для каталога предложите entity-модуль товара и объясните связь модели с представлениями."},
{"id":"architecture-fsd:feature","topic":"architecture-fsd","tab":"junior","ordinal":9,"targetLevel":"junior","angles":[],"kind":"question","title":"Что выражает Feature?","shortAnswer":"Значимое действие пользователя или бизнес-возможность.","explanation":"Кнопка сама по себе не feature: действие 'добавить в корзину' имеет смысл и правила. Низкоуровневое оформление остаётся ниже.","assessment":{"basic":"Называет действие.","confident":"Выделяет правила. Значимое действие пользователя или бизнес-возможность.","deep":"У владельца сценария выше отдельных entities, сохранив их собственные инварианты."},"followUps":[{"kind":"support","question":"Должна ли каждая маленькая UI-операция становиться feature?","expected":"Нет; нужна значимая пользовательская возможность."},{"kind":"transfer","question":"Удаление теперь требует согласования нескольких сущностей. Где разместить координацию?","expected":"У владельца сценария выше отдельных entities, сохранив их собственные инварианты."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Выделите добавление товара в корзину и отделите действие от данных товара и страницы."},
{"id":"architecture-fsd:widget","topic":"architecture-fsd","tab":"junior","ordinal":10,"targetLevel":"junior","angles":[],"kind":"question","title":"Когда нужен Widget?","shortAnswer":"Для самостоятельного крупного блока композиции с понятной ролью на странице.","explanation":"Widget может объединять entities и features. Маленький wrapper без самостоятельного смысла не обязан становиться отдельным slice.","assessment":{"basic":"Выделяет блок.","confident":"Понимает композицию. Для самостоятельного крупного блока композиции с понятной ролью на странице.","deep":"Не обязательно; допустима локальная композиция страницы без искусственного слоя."},"followUps":[{"kind":"support","question":"Какой признак делает блок самостоятельной композицией?","expected":"Понятная роль и граница крупного блока страницы."},{"kind":"transfer","question":"Блок используется только один раз и не имеет самостоятельного контракта. Нужен ли widget?","expected":"Не обязательно; допустима локальная композиция страницы без искусственного слоя."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Оцените выделение самостоятельного блока профиля в widget и определите его публичный контракт."},
{"id":"architecture-fsd:page","topic":"architecture-fsd","tab":"junior","ordinal":11,"targetLevel":"junior","angles":[],"kind":"question","title":"Что остаётся в Page?","shortAnswer":"Композиция экрана и логика, принадлежащая именно этому маршруту.","explanation":"Повторное использование не является обязательным условием Page. Выносить всё в features заранее увеличивает навигацию по проекту.","assessment":{"basic":"Собирает экран.","confident":"Оставляет локальную логику. Композиция экрана и логика, принадлежащая именно этому маршруту.","deep":"Совпадение бизнес-смысла и общего контракта, а не только текст кода."},"followUps":[{"kind":"support","question":"Кому принадлежит логика, нужная только конкретному маршруту?","expected":"Странице или её локальным модулям."},{"kind":"transfer","question":"Та же операция нужна из другого маршрута. Что проверите перед переносом?","expected":"Совпадение бизнес-смысла и общего контракта, а не только текст кода."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Маршрут собирает каталог и локальные фильтры. Определите ответственность страницы."},
{"id":"architecture-fsd:app-layer","topic":"architecture-fsd","tab":"junior","ordinal":12,"targetLevel":"junior","angles":[],"kind":"question","title":"За что отвечает App?","shortAnswer":"Инициализация, провайдеры, маршрутизация и общая сборка приложения.","explanation":"App может зависеть от нижних слоёв. Доменные правила не следует прятать в глобальной инициализации только ради удобства импорта.","assessment":{"basic":"Называет composition root.","confident":"Подключает providers. Инициализация, провайдеры, маршрутизация и общая сборка приложения.","deep":"Передать нужную возможность через контракт или использовать допустимый нижележащий адаптер, не создавать обратный импорт."},"followUps":[{"kind":"support","question":"Где собираются глобальные providers и маршруты?","expected":"На уровне App."},{"kind":"transfer","question":"Feature хочет импортировать router из App. Как развернуть зависимость?","expected":"Передать нужную возможность через контракт или использовать допустимый нижележащий адаптер, не создавать обратный импорт."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Разместите провайдеры, маршрутизацию и запуск сервисов. Объясните направление зависимостей."},
{"id":"architecture-fsd:segments","topic":"architecture-fsd","tab":"junior","ordinal":13,"targetLevel":"junior","angles":[],"kind":"question","title":"Зачем внутри slice разделять ui, model и api?","shortAnswer":"Они группируют код по технической роли внутри одной смысловой границы.","explanation":"Segments не становятся независимыми слоями всего приложения. Короткий slice может иметь простую структуру без лишних папок.","assessment":{"basic":"Знает роли segments.","confident":"Сохраняет slice cohesion. Они группируют код по технической роли внутри одной смысловой границы.","deep":"Не обязательно; структура должна отражать реальную работу, а не обязательный шаблон пустых папок."},"followUps":[{"kind":"support","question":"Что означают model, ui и api внутри slice?","expected":"Технические роли внутри одной смысловой границы."},{"kind":"transfer","question":"Ради единообразия создают пустые segments во всех slices. Есть ли польза?","expected":"Не обязательно; структура должна отражать реальную работу, а не обязательный шаблон пустых папок."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"В slice есть UI, запросы и переходы модели. Предложите segments и их назначение."},
{"id":"architecture-fsd:reuse","topic":"architecture-fsd","tab":"junior","ordinal":14,"targetLevel":"junior","angles":[],"kind":"question","title":"Когда стоит выделять общий компонент?","shortAnswer":"Когда совпадает смысл контракта и есть устойчивый сценарий совместного изменения.","explanation":"Два похожих фрагмента могут развиваться независимо. Ранняя универсализация приводит к набору флагов и сложному API.","assessment":{"basic":"Видит повторение.","confident":"Сравнивает смысл. Когда совпадает смысл контракта и есть устойчивый сценарий совместного изменения.","deep":"Возможно, сценарии расходятся; разделить реализации или явные варианты вместо универсального комбайна."},"followUps":[{"kind":"support","question":"Достаточно ли похожих строк кода для общей абстракции?","expected":"Нет; нужен общий смысл и совместная эволюция."},{"kind":"transfer","question":"После объединения параметры стали взаимно исключающими флагами. Что пересмотрите?","expected":"Возможно, сценарии расходятся; разделить реализации или явные варианты вместо универсального комбайна."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Два сценария содержат похожий код. Определите критерии объединения и сохранения независимости."},
{"id":"architecture-fsd:architecture-test","topic":"architecture-fsd","tab":"junior","ordinal":15,"targetLevel":"junior","angles":[],"kind":"question","title":"Как проверить правило импортов?","shortAnswer":"Линтером или анализом dependency graph с явными разрешёнными направлениями.","explanation":"Документ без автоматической проверки постепенно расходится с кодом. Исключения должны иметь причину и владельца.","assessment":{"basic":"Задаёт правило.","confident":"Выбирает автоматическую проверку. Линтером или анализом dependency graph с явными разрешёнными направлениями.","deep":"Она может не видеть runtime-связь; нужен явный registry/контракт и дополнительные проверки."},"followUps":[{"kind":"support","question":"Как автоматически обнаружить запрещённый импорт?","expected":"Статическим анализом зависимостей или линтером."},{"kind":"transfer","question":"Зависимость загружается динамически по строке. Что ограничивает такую проверку?","expected":"Она может не видеть runtime-связь; нужен явный registry/контракт и дополнительные проверки."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Предложите автоматическую проверку разрешённых импортов и циклов."},
{"id":"architecture-fsd:same-layer","topic":"architecture-fsd","tab":"middle","ordinal":1,"targetLevel":"middle","angles":[],"kind":"question","title":"Почему обычные FSD slices одного слоя не импортируют друг друга?","shortAnswer":"Для сохранения независимости и предотвращения горизонтальной связанности.","explanation":"Общую композицию поднимают выше, общий смысл выделяют ниже. Специальные cross-reference API entities имеют отдельный узкий контракт.","assessment":{"basic":"Знает ограничение.","confident":"Выбирает перенос композиции. Для сохранения независимости и предотвращения горизонтальной связанности.","deep":"На подходящем вышележащем уровне либо через обоснованный разрешённый контракт."},"followUps":[{"kind":"support","question":"Почему горизонтальный импорт связывает жизненные циклы slices?","expected":"Один начинает знать внутреннюю модель другого равноправного модуля."},{"kind":"transfer","question":"Оба slice нужны одному сценарию. Где собрать взаимодействие?","expected":"На подходящем вышележащем уровне либо через обоснованный разрешённый контракт."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Две соседние features импортируют друг друга. Предложите владельца взаимодействия."},
{"id":"architecture-fsd:dto-model","topic":"architecture-fsd","tab":"middle","ordinal":2,"targetLevel":"middle","angles":[],"kind":"question","title":"Где преобразовывать серверный DTO в модель UI?","shortAnswer":"На явной границе данных, принадлежащей модулю-потребителю или доменному владельцу.","explanation":"Иначе формат backend распространяется по компонентам. Не каждый DTO требует копии модели, если контракты действительно совпадают.","assessment":{"basic":"Выделяет mapping.","confident":"Не дублирует без причины. На явной границе данных, принадлежащей модулю-потребителю или доменному владельцу.","deep":"Изменить адаптер границы и контрактные тесты, сохранив стабильную внутреннюю модель."},"followUps":[{"kind":"support","question":"Обязаны ли DTO и доменная модель иметь одинаковую форму?","expected":"Нет; транспорт и внутренние инварианты могут различаться."},{"kind":"transfer","question":"Backend переименовал поле без изменения смысла. Как ограничить последствия?","expected":"Изменить адаптер границы и контрактные тесты, сохранив стабильную внутреннюю модель."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Ответ API неудобен для UI. Спроектируйте преобразование DTO и ответственность за него."},
{"id":"architecture-fsd:dependency-inversion","topic":"architecture-fsd","tab":"middle","ordinal":3,"targetLevel":"middle","angles":[],"kind":"question","title":"Как инверсия зависимостей помогает тестируемости?","shortAnswer":"Высокоуровневая логика получает нужный контракт, а конкретная инфраструктура подключается снаружи.","explanation":"Интерфейс должен отражать потребность потребителя. Абстракция с точной копией fetch без иной пользы может быть лишней.","assessment":{"basic":"Определяет порт.","confident":"Внедряет реализацию. Высокоуровневая логика получает нужный контракт, а конкретная инфраструктура подключается снаружи.","deep":"Подключить адаптер без изменения доменных правил и проверить одинаковый контракт, не только наличие интерфейса."},"followUps":[{"kind":"support","question":"Кто задаёт контракт нужной возможности?","expected":"Потребляющая высокоуровневая логика, исходя из своей потребности."},{"kind":"transfer","question":"Появился второй транспорт. Как проверить ценность инверсии?","expected":"Подключить адаптер без изменения доменных правил и проверить одинаковый контракт, не только наличие интерфейса."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Доменное правило вызывает конкретный HTTP-клиент. Предложите инверсию зависимости."},
{"id":"architecture-fsd:form-boundary","topic":"architecture-fsd","tab":"middle","ordinal":4,"targetLevel":"middle","angles":[],"kind":"question","title":"Где разместить форму редактирования профиля?","shortAnswer":"По владельцу сценария; локальный draft отделить от server-state сущности.","explanation":"Форма не должна мутировать общий кеш до подтверждения без явного optimistic-контракта. Валидация UI и сервера имеют разные задачи.","assessment":{"basic":"Разделяет draft/entity.","confident":"Определяет feature boundary. По владельцу сценария; локальный draft отделить от server-state сущности.","deep":"Явный конфликт/слияние или сохранение черновика с новой базой, без молчаливой потери ввода."},"followUps":[{"kind":"support","question":"Почему черновик не равен текущей серверной записи?","expected":"Он содержит неподтверждённые локальные изменения."},{"kind":"transfer","question":"Сервер обновил запись, пока форма грязная. Что должно произойти?","expected":"Явный конфликт/слияние или сохранение черновика с новой базой, без молчаливой потери ввода."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Форма редактирует серверную сущность. Определите владельца черновика и подтверждённых данных."},
{"id":"architecture-fsd:route-state","topic":"architecture-fsd","tab":"middle","ordinal":5,"targetLevel":"middle","angles":[],"kind":"question","title":"Какие фильтры стоит хранить в URL?","shortAnswer":"Те, которые нужно разделять ссылкой и восстанавливать навигацией.","explanation":"Секретные и очень объёмные данные туда не помещают. Парсинг URL — недоверенная граница с defaults и валидацией.","assessment":{"basic":"Выбирает shareable state.","confident":"Проверяет URL-параметры. Те, которые нужно разделять ссылкой и восстанавливать навигацией.","deep":"Согласованное обновление URL без затирания чужих параметров и корректную историю навигации."},"followUps":[{"kind":"support","question":"Какие фильтры полезно восстанавливать из URL?","expected":"Те, что определяют разделяемое ссылкой представление."},{"kind":"transfer","question":"Два компонента одновременно меняют разные query-параметры. Что защитите?","expected":"Согласованное обновление URL без затирания чужих параметров и корректную историю навигации."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Каталогу нужны разделяемые ссылкой фильтры. Выберите состояние URL и восстановление навигации."},
{"id":"architecture-fsd:business-rule","topic":"architecture-fsd","tab":"middle","ordinal":6,"targetLevel":"middle","angles":[],"kind":"question","title":"Куда поместить правило доступности действия?","shortAnswer":"В модуль, владеющий доменным инвариантом, а UI только отображает результат.","explanation":"Проверка на клиенте улучшает UX, но сервер остаётся границей авторизации. Дублирование правила в нескольких кнопках расходится.","assessment":{"basic":"Выделяет инвариант.","confident":"Централизует доменную проверку. В модуль, владеющий доменным инвариантом, а UI только отображает результат.","deep":"Сервер подтверждает итог, клиент учитывает версию/ответ и не выдаёт локальный расчёт за окончательную гарантию."},"followUps":[{"kind":"support","question":"Должно ли одно правило скидки копироваться в разные компоненты?","expected":"Нет; нужен явный доменный владелец."},{"kind":"transfer","question":"Сервер применил другую версию правила. Как согласовать клиентскую подсказку?","expected":"Сервер подтверждает итог, клиент учитывает версию/ответ и не выдаёт локальный расчёт за окончательную гарантию."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Правило скидки повторяется в компонентах. Определите владельца инварианта и интерфейс UI."},
{"id":"architecture-fsd:barrel-cycle","topic":"architecture-fsd","tab":"middle","ordinal":7,"targetLevel":"middle","angles":[],"kind":"question","title":"Почему index.ts может создавать неожиданные циклы?","shortAnswer":"Он собирает экспорты и расширяет граф импортов, особенно при внутренних импортax через собственный barrel.","explanation":"Внутри slice обычно яснее относительные пути, снаружи — public API. Barrel не гарантирует tree-shaking любого side effect.","assessment":{"basic":"Находит cycle через barrel.","confident":"Разделяет внутренние/внешние импорты. Он собирает экспорты и расширяет граф импортов, особенно при внутренних импортax через собственный barrel.","deep":"Исследовать смысловую зависимость и владельца композиции; файл index не единственная причина цикла."},"followUps":[{"kind":"support","question":"Почему импорт собственного index из внутреннего файла рискован?","expected":"Может замкнуть граф через агрегированные экспорты."},{"kind":"transfer","question":"Barrel удалили, но цикл остался через другой путь. Что дальше?","expected":"Исследовать смысловую зависимость и владельца композиции; файл index не единственная причина цикла."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Проследите граф index.ts из примера и устраните цикл без раскрытия лишних деталей.","questionCode":"entities/product/index.ts → ui/ProductCard.tsx\nui/ProductCard.tsx → index.ts → model/product.ts\nmodel/product.ts → ui/formatProduct.ts","questionCodeLanguage":"text"},
{"id":"architecture-fsd:cross-reference","topic":"architecture-fsd","tab":"middle","ordinal":8,"targetLevel":"middle","angles":[],"kind":"question","title":"Для чего FSD entities используют @x API?","shortAnswer":"Для явных необходимых связей между сущностями при сохранении ограниченной поверхности.","explanation":"Это не общий обход запрета горизонтальных импортов. Связь должна отражать домен и быть направленной.","assessment":{"basic":"Знает узкое исключение.","confident":"Ограничивает экспорт. Для явных необходимых связей между сущностями при сохранении ограниченной поверхности.","deep":"Это снимает смысл ограниченной границы; пересмотреть владельца и разрешённые операции."},"followUps":[{"kind":"support","question":"Что должно ограничивать межсущностный @x-контракт?","expected":"Конкретную необходимую связь и минимальную поверхность."},{"kind":"transfer","question":"Через @x начали экспортировать весь slice. Как оцените?","expected":"Это снимает смысл ограниченной границы; пересмотреть владельца и разрешённые операции."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Оцените @x-контракт product/order из примера: необходимость связи и минимальную поверхность.","questionCode":"entities/\n  product/\n    @x/\n      order.ts\n    index.ts\n  order/\n    model/","questionCodeLanguage":"text"},
{"id":"architecture-fsd:testing-boundaries","topic":"architecture-fsd","tab":"middle","ordinal":9,"targetLevel":"middle","angles":[],"kind":"question","title":"Как выбрать уровень теста для модуля?","shortAnswer":"Проверять контракт на самом дешёвом уровне, который обнаруживает нужный риск.","explanation":"Чистые правила удобно тестировать отдельно, взаимодействие UI/сети — интеграционно. Тесты внутренних файлов мешают безопасному рефакторингу.","assessment":{"basic":"Соотносит риск и уровень.","confident":"Тестирует public behavior. Проверять контракт на самом дешёвом уровне, который обнаруживает нужный риск.","deep":"На границе преобразования данных и интеграции, где возникает конкретная потеря смысла."},"followUps":[{"kind":"support","question":"Нужно ли проверять чистое правило только браузерным тестом?","expected":"Нет; более дешёвый уровень может надёжно выявить риск."},{"kind":"transfer","question":"Правило верно отдельно, но адаптер теряет timezone. Где нужен тест?","expected":"На границе преобразования данных и интеграции, где возникает конкретная потеря смысла."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Выберите уровни тестирования чистого правила, API-адаптера и формы по рискам."},
{"id":"architecture-fsd:configuration","topic":"architecture-fsd","tab":"middle","ordinal":10,"targetLevel":"middle","angles":[],"kind":"question","title":"Где хранить окружение и конфигурацию?","shortAnswer":"В явном конфигурационном модуле с проверкой при запуске, не в разбросанных process/env-чтениях.","explanation":"Клиентский bundle публичен: переменная окружения в нём не секрет. Runtime-конфигурация и build-time имеют разный lifecycle.","assessment":{"basic":"Централизует чтение.","confident":"Валидирует значения. В явном конфигурационном модуле с проверкой при запуске, не в разбросанных process/env-чтениях.","deep":"Валидация каждой версии, атомарное применение и политика отката; стартовой проверки недостаточно."},"followUps":[{"kind":"support","question":"Когда лучше выявить отсутствие обязательной настройки?","expected":"При запуске соответствующей границы, до скрытого отказа сценария."},{"kind":"transfer","question":"Настройка обновляется без перезапуска. Как изменится контракт?","expected":"Валидация каждой версии, атомарное применение и политика отката; стартовой проверки недостаточно."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Настройки среды читаются повсюду. Предложите единую проверяемую границу конфигурации."},
{"id":"architecture-fsd:error-layers","topic":"architecture-fsd","tab":"middle","ordinal":11,"targetLevel":"middle","angles":[],"kind":"question","title":"На каком уровне преобразовывать ошибки?","shortAnswer":"Транспорт распознаёт технический сбой, домен — смысл, UI — пользовательское действие.","explanation":"Один глобальный catch с одинаковым toast теряет контекст. Ожидаемые и неожиданные ошибки требуют разных контрактов.","assessment":{"basic":"Разделяет уровни.","confident":"Сохраняет cause/code. Транспорт распознаёт технический сбой, домен — смысл, UI — пользовательское действие.","deep":"Нормализовать по серверному коду/контексту на границе, не только по статусу."},"followUps":[{"kind":"support","question":"Должен ли UI знать все детали HTTP-клиента?","expected":"Нет; ему нужен понятный смысл ошибки и возможное действие."},{"kind":"transfer","question":"Один HTTP 409 имеет два доменных смысла. Как различить?","expected":"Нормализовать по серверному коду/контексту на границе, не только по статусу."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Распределите распознавание технического сбоя, доменный смысл и пользовательское действие по слоям."},
{"id":"architecture-fsd:dependency-budget","topic":"architecture-fsd","tab":"middle","ordinal":12,"targetLevel":"middle","angles":[],"kind":"question","title":"Как контролировать рост связности проекта?","shortAnswer":"Измерять направления и число зависимостей, выделять владельцев и проверять новые связи на review.","explanation":"Число импортов само не показатель качества. Важны причины совместного изменения и стоимость распространения изменений.","assessment":{"basic":"Строит graph.","confident":"Связывает метрики с изменениями. Измерять направления и число зависимостей, выделять владельцев и проверять новые связи на review.","deep":"Стоимость координации, стабильность контракта и альтернативу локального дублирования."},"followUps":[{"kind":"support","question":"Доказывает ли малое число импортов слабую связанность?","expected":"Нет; один широкий контракт может связывать очень многое."},{"kind":"transfer","question":"Новая зависимость экономит код, но связывает релизы команд. Что оцените?","expected":"Стоимость координации, стабильность контракта и альтернативу локального дублирования."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Команда быстро добавляет межмодульные связи. Предложите ограничения, владельцев и критерии полезности."},
{"id":"architecture-fsd:local-global","topic":"architecture-fsd","tab":"middle","ordinal":13,"targetLevel":"middle","angles":[],"kind":"question","title":"Как решить, выносить ли состояние из компонента?","shortAnswer":"По владельцу и требуемому сроку жизни, не по размеру объекта.","explanation":"Поднятие state расширяет область обновления и связанность. Shared access может быть решён композицией, context или store по масштабу.","assessment":{"basic":"Определяет lifetime.","confident":"Сравнивает варианты. По владельцу и требуемому сроку жизни, не по размеру объекта.","deep":"Поднять владельца или выбрать сохранение согласно требуемому сроку жизни."},"followUps":[{"kind":"support","question":"Делает ли большой размер объекта состояние глобальным?","expected":"Нет; важны владелец и срок жизни."},{"kind":"transfer","question":"Маленький флаг должен переживать смену маршрута. Что измените?","expected":"Поднять владельца или выбрать сохранение согласно требуемому сроку жизни."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Выберите место состояния формы и общего выбора по сроку жизни и совместному доступу."},
{"id":"architecture-fsd:legacy-adapter","topic":"architecture-fsd","tab":"middle","ordinal":14,"targetLevel":"middle","angles":[],"kind":"question","title":"Как подключить новый модуль к legacy API?","shortAnswer":"Через адаптер, переводящий старый контракт в новый на ограниченной границе.","explanation":"Не нужно распространять legacy-формат по новой модели. Временный адаптер должен иметь тесты контракта и план удаления.","assessment":{"basic":"Выделяет adapter.","confident":"Локализует несовместимость. Через адаптер, переводящий старый контракт в новый на ограниченной границе.","deep":"Адаптер должен явно моделировать эффект и ошибки, не выдавая его за чистую функцию."},"followUps":[{"kind":"support","question":"Зачем адаптер переводит старый контракт в новый?","expected":"Локализует несовместимость и ограничивает её распространение."},{"kind":"transfer","question":"Старый API имеет побочный эффект при чтении. Что учесть?","expected":"Адаптер должен явно моделировать эффект и ошибки, не выдавая его за чистую функцию."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Новый модуль использует старый API. Спроектируйте адаптер legacy-контракта."},
{"id":"architecture-fsd:feature-toggle","topic":"architecture-fsd","tab":"middle","ordinal":15,"targetLevel":"middle","angles":[],"kind":"question","title":"Как безопасно использовать feature flags?","shortAnswer":"Определить владельца, срок жизни, допустимые комбинации и fallback.","explanation":"Флаг не должен жить в каждой функции бесконтрольно. После rollout старую ветку удаляют, иначе число состояний системы растёт.","assessment":{"basic":"Задаёт lifecycle флага.","confident":"Ограничивает комбинации. Определить владельца, срок жизни, допустимые комбинации и fallback.","deep":"Обратную совместимость данных и реальность rollback; выключение UI не откатывает миграцию."},"followUps":[{"kind":"support","question":"Что кроме значения флага нужно определить?","expected":"Владельца, срок жизни, fallback и допустимые комбинации."},{"kind":"transfer","question":"Флаг выключили после создания данных новым форматом. Что проверите?","expected":"Обратную совместимость данных и реальность rollback; выключение UI не откатывает миграцию."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Спроектируйте временный флаг: владельца, состояния, fallback и план удаления."},
{"id":"architecture-fsd:architecture-choice","topic":"architecture-fsd","tab":"senior","ordinal":1,"targetLevel":"senior","angles":[],"kind":"case","title":"Как выбрать архитектуру нового продукта при неопределённых требованиях?","shortAnswer":"Начать с минимальных устойчивых границ и записать причины решений и условия пересмотра.","explanation":"Неопределённость не оправдывает ни монолит без границ, ни максимальную слоистость. Дороже всего преждевременно закрепить неверные зависимости.","assessment":{"basic":"Выделяет известные ограничения.","confident":"Оставляет обратимые решения. Начать с минимальных устойчивых границ и записать причины решений и условия пересмотра.","deep":"Ownership, частоту конфликтов и независимость поставки на измеренных сценариях, а не автоматически число слоёв."},"followUps":[{"kind":"support","question":"Почему структура папок сама не доказывает правильность архитектуры?","expected":"Она не показывает реальные причины изменений и контракты."},{"kind":"transfer","question":"Команда выросла вдвое. Какие условия решения пересмотрите?","expected":"Ownership, частоту конфликтов и независимость поставки на измеренных сценариях, а не автоматически число слоёв."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Выберите минимальные границы растущего продукта и условия пересмотра решения. Команда небольшая, требования ещё меняются; стоимость сопровождения границ должна быть оправдана."},
{"id":"architecture-fsd:bounded-context","topic":"architecture-fsd","tab":"senior","ordinal":2,"targetLevel":"senior","angles":[],"kind":"case","title":"Как разделять крупную предметную область?","shortAnswer":"По моделям, языку и инвариантам, а не только таблицам backend.","explanation":"Одинаковое слово может иметь разные значения в контекстах. Связь между ними оформляют переводом контракта, а не общим гигантским типом.","assessment":{"basic":"Находит разные модели.","confident":"Определяет контекстные границы. По моделям, языку и инвариантам, а не только таблицам backend.","deep":"Явные контексты и адаптеры между моделями, без общей сущности только по имени."},"followUps":[{"kind":"support","question":"Должны ли границы фронтенда копировать таблицы backend?","expected":"Нет; важны язык, модели и инварианты сценариев."},{"kind":"transfer","question":"Одинаковое слово «клиент» имеет два смысла в продукте. Как избежать смешения?","expected":"Явные контексты и адаптеры между моделями, без общей сущности только по имени."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"В двух областях по-разному трактуют заказ. Определите границы моделей и взаимодействие. Обе области выпускаются независимо и имеют разные правила допустимых состояний заказа."},
{"id":"architecture-fsd:frontend-monolith","topic":"architecture-fsd","tab":"senior","ordinal":3,"targetLevel":"senior","angles":[],"kind":"case","title":"Когда модульный монолит лучше микрофронтендов?","shortAnswer":"Когда команды и релизы ещё не требуют независимого runtime/deployment, а единый UX важнее изоляции.","explanation":"Микрофронтенды добавляют версии, общие зависимости и интеграционный протокол. Выбирать их нужно по организационной потребности, не моде.","assessment":{"basic":"Сравнивает выгоды/цену.","confident":"Учитывает организацию. Когда команды и релизы ещё не требуют независимого runtime/deployment, а единый UX важнее изоляции.","deep":"Границу независимости, общий UX и контракты версий; не дробить критичный процесс без координации."},"followUps":[{"kind":"support","question":"Всегда ли несколько команд требуют микрофронтенды?","expected":"Нет; независимость runtime/deploy должна оправдывать стоимость."},{"kind":"transfer","question":"Командам нужны отдельные релизы, но общий checkout атомарен. Что исследуете?","expected":"Границу независимости, общий UX и контракты версий; не дробить критичный процесс без координации."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Сравните модульный монолит и микрофронтенды при общем релизе и едином UX. Нет требования независимого runtime, но команды хотят уменьшить конфликты изменений."},
{"id":"architecture-fsd:migration-strangler","topic":"architecture-fsd","tab":"senior","ordinal":4,"targetLevel":"senior","angles":[],"kind":"case","title":"Как постепенно заменить большой legacy frontend?","shortAnswer":"Выбрать вертикальный сценарий, создать совместимую границу и переносить ответственность по частям.","explanation":"Полная перепись задерживает обратную связь. Strangler-подход требует маршрутизации, общего UX и удаления старого пути после переключения.","assessment":{"basic":"Выбирает slice сценария.","confident":"Проектирует coexistence. Выбрать вертикальный сценарий, создать совместимую границу и переносить ответственность по частям.","deep":"Явное владение записью, совместимый формат и переключение/согласование, а не два независимых писателя."},"followUps":[{"kind":"support","question":"Что делает вертикальный сценарий удобной единицей миграции?","expected":"Он даёт проверяемый пользовательский результат через несколько слоёв."},{"kind":"transfer","question":"Новый и старый пути пишут в одно хранилище. Как избежать конфликта?","expected":"Явное владение записью, совместимый формат и переключение/согласование, а не два независимых писателя."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Спланируйте замену legacy-экрана через работающий вертикальный сценарий. Переписать продукт сразу нельзя, а старый путь должен работать до переключения пользователей."},
{"id":"architecture-fsd:cross-team-api","topic":"architecture-fsd","tab":"senior","ordinal":5,"targetLevel":"senior","angles":[],"kind":"case","title":"Как согласовать публичные API модулей нескольких команд?","shortAnswer":"Определить владельцев, совместимость, consumer-кейсы и процесс deprecation.","explanation":"Общий репозиторий не отменяет контрактов. Изменение внутреннего файла не должно требовать синхронного релиза всех потребителей.","assessment":{"basic":"Назначает ownership.","confident":"Планирует compatibility. Определить владельцев, совместимость, consumer-кейсы и процесс deprecation.","deep":"Совместимый переходный контракт, версии и измерение использования до удаления старого пути."},"followUps":[{"kind":"support","question":"Кто должен отвечать за deprecation публичного контракта?","expected":"Определённый владелец с учётом потребителей."},{"kind":"transfer","question":"Не все команды могут обновиться одновременно. Как выпустить изменение?","expected":"Совместимый переходный контракт, версии и измерение использования до удаления старого пути."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Спроектируйте межкомандный API с владельцем, consumer-проверками и deprecation. Обновления потребителей не синхронны; удаление старой версии должно быть проверяемым."},
{"id":"architecture-fsd:resilience-front","topic":"architecture-fsd","tab":"senior","ordinal":6,"targetLevel":"senior","angles":[],"kind":"case","title":"Как проектировать frontend для частичного отказа backend?","shortAnswer":"Разделить независимые области, определить деградацию, таймауты и повтор по типу операции.","explanation":"Один endpoint не должен без необходимости блокировать весь экран. Но показ несогласованных данных может быть хуже явной ошибки.","assessment":{"basic":"Выделяет failure domains.","confident":"Определяет degraded UX. Разделить независимые области, определить деградацию, таймауты и повтор по типу операции.","deep":"Ограничение конкуренции и приоритеты ресурсов; визуальная boundary не изолирует всю инфраструктуру."},"followUps":[{"kind":"support","question":"Должен ли отказ рекомендаций блокировать оплату?","expected":"Только если есть реальная зависимость; обычно области изолируют."},{"kind":"transfer","question":"Рекомендации используют тот же исчерпанный пул запросов. Что ещё нужно?","expected":"Ограничение конкуренции и приоритеты ресурсов; визуальная boundary не изолирует всю инфраструктуру."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Часть сервисов недоступна. Определите независимые области UI и деградацию сценария. Основная операция должна оставаться доступной при отказе необязательного сервиса."},
{"id":"architecture-fsd:security-boundaries","topic":"architecture-fsd","tab":"senior","ordinal":7,"targetLevel":"senior","angles":[],"kind":"case","title":"Где в frontend проходят границы доверия?","shortAnswer":"На внешнем вводе, HTML, URL, storage, сообщениях и server/client serialization.","explanation":"TypeScript и скрытая кнопка не являются защитой. Сервер проверяет полномочия, клиент ограничивает опасные преобразования и утечки.","assessment":{"basic":"Перечисляет границы.","confident":"Разделяет auth/UI. На внешнем вводе, HTML, URL, storage, сообщениях и server/client serialization.","deep":"На входе и конечной HTML-вставке с валидацией/санитаризацией по контексту, независимо от названия «внутренний»."},"followUps":[{"kind":"support","question":"Можно ли считать localStorage доверенным источником структуры данных?","expected":"Нет; это внешняя граница чтения."},{"kind":"transfer","question":"Внутренний сервис начал принимать HTML от партнёра. Где новая граница?","expected":"На входе и конечной HTML-вставке с валидацией/санитаризацией по контексту, независимо от названия «внутренний»."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Найдите границы доверия URL, storage, сообщений и внешних данных; определите проверки. Один и тот же ввод попадает в разные контексты отображения и сохранения."},
{"id":"architecture-fsd:architecture-evidence","topic":"architecture-fsd","tab":"senior","ordinal":8,"targetLevel":"senior","angles":[],"kind":"case","title":"Как понять, что архитектура действительно улучшилась?","shortAnswer":"Сравнить скорость безопасных изменений, распространение зависимостей, дефекты и опыт команды.","explanation":"Количество папок не метрика результата. Нужен конкретный сценарий изменения и свидетельство уменьшения его стоимости.","assessment":{"basic":"Выбирает outcome-метрики.","confident":"Сравнивает реальные изменения. Сравнить скорость безопасных изменений, распространение зависимостей, дефекты и опыт команды.","deep":"Сопоставить метрики качества и координации; одна скорость не подтверждает успех решения."},"followUps":[{"kind":"support","question":"Доказывает ли меньшее число файлов улучшение архитектуры?","expected":"Нет; нужны данные о безопасных изменениях и дефектах."},{"kind":"transfer","question":"Скорость разработки выросла, но выросли межкомандные регрессии. Как оцените?","expected":"Сопоставить метрики качества и координации; одна скорость не подтверждает успех решения."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Предложите эксперимент, показывающий влияние архитектуры на безопасные изменения. Команда не может позволить полную перестройку без данных о пользе пилота."},
{"id":"architecture-fsd:domain-frontend","topic":"architecture-fsd","tab":"senior","ordinal":9,"targetLevel":"senior","angles":[],"kind":"case","title":"Когда frontend нуждается в доменном слое?","shortAnswer":"Когда есть существенные клиентские правила, переходы и несколько представлений одной модели.","explanation":"Простой CRUD может не нуждаться в глубокой модели. Слой оправдан, если отделяет устойчивые инварианты от UI и транспорта.","assessment":{"basic":"Оценивает сложность правил.","confident":"Выделяет чистую модель. Когда есть существенные клиентские правила, переходы и несколько представлений одной модели.","deep":"Не создавать лишний доменный слой без реальной вариативности и инвариантов."},"followUps":[{"kind":"support","question":"Когда клиенту нужна отдельная доменная модель?","expected":"При существенных правилах, переходах и нескольких представлениях."},{"kind":"transfer","question":"Клиент лишь показывает неизменённый DTO одной страницы. Что пересмотрите?","expected":"Не создавать лишний доменный слой без реальной вариативности и инвариантов."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Оцените доменную модель для клиента со сложными переходами и несколькими представлениями. Правила должны одинаково работать в нескольких UI-сценариях без зависимости от React."},
{"id":"architecture-fsd:offline-architecture","topic":"architecture-fsd","tab":"senior","ordinal":10,"targetLevel":"senior","angles":[],"kind":"case","title":"Какие решения нужны offline-first продукту?","shortAnswer":"Локальный источник данных, протокол синхронизации, версии, конфликты и понятный статус пользователю.","explanation":"Service worker и кеш ответов не решают конфликт записей. Нужно определить, какие действия разрешены без сети.","assessment":{"basic":"Различает caching/sync.","confident":"Проектирует conflict policy. Локальный источник данных, протокол синхронизации, версии, конфликты и понятный статус пользователю.","deep":"Явный протокол версий/слияния и пользовательский статус, а не порядок случайного reconnect."},"followUps":[{"kind":"support","question":"Равна ли запись в локальную очередь успешной серверной операции?","expected":"Нет; это неподтверждённое локальное намерение."},{"kind":"transfer","question":"Два устройства изменили один документ offline. Что решает конфликт?","expected":"Явный протокол версий/слияния и пользовательский статус, а не порядок случайного reconnect."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Спроектируйте offline-редактирование с локальными данными, синхронизацией и статусом операции. Пользователь может менять данные несколько часов без связи и закрывать приложение."},
{"id":"architecture-fsd:observability-system","topic":"architecture-fsd","tab":"senior","ordinal":11,"targetLevel":"senior","angles":[],"kind":"case","title":"Как заложить наблюдаемость в архитектуру frontend?","shortAnswer":"Определить события сценариев, ошибки, performance и корреляцию с серверными операциями.","explanation":"Логи без контекста не объясняют сбой, но чрезмерный payload раскрывает данные. Нужны sampling, sanitization и владельцы сигналов.","assessment":{"basic":"Выбирает полезные события.","confident":"Связывает client/server. Определить события сценариев, ошибки, performance и корреляцию с серверными операциями.","deep":"Отдельные id попыток и устойчивый id операции, сохраняя приватность и причинную цепочку."},"followUps":[{"kind":"support","question":"Что связывает UI-сбой с серверной операцией?","expected":"Безопасный корреляционный идентификатор и события сценария."},{"kind":"transfer","question":"Операция повторена после timeout. Как различить попытки и бизнес-действие?","expected":"Отдельные id попыток и устойчивый id операции, сохраняя приватность и причинную цепочку."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Спроектируйте наблюдаемость пользовательского сценария и связь с серверными операциями. Нужна диагностика частичных отказов без записи персонального содержимого форм."},
{"id":"architecture-fsd:decision-record","topic":"architecture-fsd","tab":"senior","ordinal":12,"targetLevel":"senior","angles":[],"kind":"case","title":"Что делает ADR полезным спустя год?","shortAnswer":"Контекст, выбранный вариант, альтернативы, последствия и условия пересмотра.","explanation":"ADR фиксирует причину, а не только текущую структуру. Устаревшее решение помечают заменённым, сохраняя связь с новым.","assessment":{"basic":"Пишет rationale.","confident":"Указывает последствия. Контекст, выбранный вариант, альтернативы, последствия и условия пересмотра.","deep":"Пересмотреть решение по записанным условиям и создать новое состояние решения, не переписывая историю молча."},"followUps":[{"kind":"support","question":"Зачем фиксировать отвергнутые альтернативы?","expected":"Чтобы понимать исходные ограничения и основания выбора."},{"kind":"transfer","question":"Ключевое ограничение исчезло. Что делать с ADR?","expected":"Пересмотреть решение по записанным условиям и создать новое состояние решения, не переписывая историю молча."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Запишите решение с контекстом, альтернативами, последствиями и условиями пересмотра. Решение принято при временном ограничении ресурсов; будущая команда должна понять, когда его пересмотреть."},
{"id":"architecture-fsd:product-variance","topic":"architecture-fsd","tab":"senior","ordinal":13,"targetLevel":"senior","angles":[],"kind":"case","title":"Как спроектировать несколько продуктовых вариантов без леса if?","shortAnswer":"Выделить осмысленные вариации через композицию, конфигурацию или стратегии.","explanation":"Универсальный компонент со всеми флагами создаёт комбинаторный взрыв. Но копирование всего продукта тоже затрудняет общие исправления.","assessment":{"basic":"Находит оси вариации.","confident":"Выбирает composition boundary. Выделить осмысленные вариации через композицию, конфигурацию или стратегии.","deep":"Типизированные/валидируемые варианты и тесты допустимых комбинаций вместо произвольной матрицы флагов."},"followUps":[{"kind":"support","question":"Чем стратегия отличается от десятков флагов внутри одного компонента?","expected":"Явной границей варианта поведения и проверяемым контрактом."},{"kind":"transfer","question":"Две конфигурации требуют несовместимых правил. Как выразить запрет?","expected":"Типизированные/валидируемые варианты и тесты допустимых комбинаций вместо произвольной матрицы флагов."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Варианты продукта различаются поведением. Предложите композицию с ясными границами вариантов. Варианты поставляются разным клиентам, но не все комбинации поведения допустимы."},
{"id":"architecture-fsd:architecture-enforcement","topic":"architecture-fsd","tab":"senior","ordinal":14,"targetLevel":"senior","angles":[],"kind":"case","title":"Какие ограничения архитектуры проверять автоматически?","shortAnswer":"Направления импортов, публичные входы, циклы и запрещённые зависимости.","explanation":"Автоматика не проверяет смысл доменной границы полностью. Нужны review и периодический аудит исключений, иначе правила превращаются в формальность.","assessment":{"basic":"Выбирает проверяемые правила.","confident":"Отделяет смысл от синтаксиса. Направления импортов, публичные входы, циклы и запрещённые зависимости.","deep":"Смысловую связность и ширину ответственности; синтаксические проверки не заменяют архитектурный анализ."},"followUps":[{"kind":"support","question":"Что статически проверяется у импортов?","expected":"Направления, публичные входы, циклы и запрещённые связи."},{"kind":"transfer","question":"Код проходит правила, но один модуль знает весь домен. Что ещё оценивать?","expected":"Смысловую связность и ширину ответственности; синтаксические проверки не заменяют архитектурный анализ."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Определите автоматические правила импортов, публичных входов и циклов. Legacy-нарушения уже существуют; правила должны предотвращать новые и позволять поэтапное исправление."},
{"id":"architecture-fsd:evolution-plan","topic":"architecture-fsd","tab":"senior","ordinal":15,"targetLevel":"senior","angles":[],"kind":"case","title":"Как планировать архитектурное изменение без остановки продукта?","shortAnswer":"Разбить на совместимые шаги с критериями завершения, наблюдаемостью и rollback.","explanation":"Каждый шаг должен уменьшать конкретный риск или переносить ответственность. Бесконечный промежуточный слой становится новой legacy-системой.","assessment":{"basic":"Строит последовательность.","confident":"Определяет exit criteria. Разбить на совместимые шаги с критериями завершения, наблюдаемостью и rollback.","deep":"Подготовить совместимую схему, резерв/миграцию и отдельный план восстановления; обычного отката кода недостаточно."},"followUps":[{"kind":"support","question":"Что делает шаг миграции обратимым?","expected":"Совместимые контракты, известный rollback и наблюдаемые критерии."},{"kind":"transfer","question":"Шаг меняет формат сохранённых данных необратимо. Как измените выпуск?","expected":"Подготовить совместимую схему, резерв/миграцию и отдельный план восстановления; обычного отката кода недостаточно."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Разбейте миграцию на совместимые шаги с критериями завершения и восстановлением. Релизы продолжаются, а каждый шаг должен оставлять рабочий продукт и понятную границу отката."},
{"id":"architecture-fsd:fsd-not-ui","topic":"architecture-fsd","tab":"advanced","ordinal":1,"targetLevel":"middle","angles":["nuance"],"kind":"question","title":"Почему слои FSD не равны визуальной вложенности?","shortAnswer":"Они отражают ответственность и зависимости, а не DOM-дерево.","explanation":"Feature может не иметь UI, entity может содержать представление. Визуальный родитель не обязательно имеет более высокий архитектурный уровень.","assessment":{"basic":"Различает два дерева.","confident":"Приводит non-UI feature. Они отражают ответственность и зависимости, а не DOM-дерево.","deep":"Не автоматически; собрать композицию на подходящем уровне по правилам зависимостей."},"followUps":[{"kind":"support","question":"Должна ли вложенность DOM определять направление импортов?","expected":"Нет; направление отражает ответственность и слои."},{"kind":"transfer","question":"Один widget визуально вложен в другой. Разрешает ли это импорт соседнего slice?","expected":"Не автоматически; собрать композицию на подходящем уровне по правилам зависимостей."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Команда копирует DOM-вложенность в FSD. Оцените подход и предложите смысловые границы."},
{"id":"architecture-fsd:shared-business","topic":"architecture-fsd","tab":"advanced","ordinal":2,"targetLevel":"middle","angles":["engineering","nuance"],"kind":"case","title":"Почему вынос общей бизнес-функции в Shared может ухудшить архитектуру?","shortAnswer":"Shared теряет независимость от домена и становится скрытым центром бизнес-логики.","explanation":"Повторение между slices может означать неверную границу владения. Иногда композиция выше либо доменный модуль ниже точнее.","assessment":{"basic":"Видит скрытый домен.","confident":"Ищет владельца. Shared теряет независимость от домена и становится скрытым центром бизнес-логики.","deep":"Совпадение смысла, владельца и эволюции; переиспользование не отменяет доменную принадлежность."},"followUps":[{"kind":"support","question":"Почему общий discountCalculator может не принадлежать Shared?","expected":"Он выражает доменное правило, даже если используется часто."},{"kind":"transfer","question":"Правило стало одинаковым в двух продуктах. Что проверить перед переносом?","expected":"Совпадение смысла, владельца и эволюции; переиспользование не отменяет доменную принадлежность."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"В Shared накопились доменные правила. Предложите возвращение ответственности владельцам."},
{"id":"architecture-fsd:barrel-treeshake","topic":"architecture-fsd","tab":"advanced","ordinal":3,"targetLevel":"middle","angles":["nuance"],"kind":"question","title":"Гарантирует ли public index.ts маленький bundle?","shortAnswer":"Нет; tree-shaking зависит от модулей, side effects и bundler.","explanation":"Barrel задаёт API, но не гарантирует оптимальный граф загрузки. Нужны bundle-анализ и аккуратные entrypoints для тяжёлых частей.","assessment":{"basic":"Различает API/bundle.","confident":"Учитывает side effects. Нет; tree-shaking зависит от модулей, side effects и bundler.","deep":"Побочные эффекты и границы entry points на реальной сборке, не только количество экспортов."},"followUps":[{"kind":"support","question":"Гарантирует ли index.ts удаление неиспользуемого кода?","expected":"Нет; влияют модули, side effects и bundler."},{"kind":"transfer","question":"Пакет регистрирует плагины при импорте. Что проверить в bundle?","expected":"Побочные эффекты и границы entry points на реальной сборке, не только количество экспортов."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Все экспорты идут через index.ts. Оцените утверждение о гарантированном tree-shaking."},
{"id":"architecture-fsd:entity-cycle","topic":"architecture-fsd","tab":"advanced","ordinal":4,"targetLevel":"senior","angles":["engineering"],"kind":"case","title":"Две entities импортируют друг друга: как разорвать цикл?","shortAnswer":"Выяснить владельца связи, вынести композицию выше либо сделать направленный @x-контракт.","explanation":"Механический перенос типов в Shared может только спрятать цикл смысла. Нужна модель, в которой ответственность определена.","assessment":{"basic":"Находит причину связи.","confident":"Выбирает направленный контракт. Выяснить владельца связи, вынести композицию выше либо сделать направленный @x-контракт.","deep":"В модуле отчёта выше сущностей, не добавляя глобальный взаимный импорт."},"followUps":[{"kind":"support","question":"Что означает цикл двух сущностей для владения связью?","expected":"Возможно, связь не имеет явного владельца."},{"kind":"transfer","question":"Связь используется только в одном отчёте. Где разумна композиция?","expected":"В модуле отчёта выше сущностей, не добавляя глобальный взаимный импорт."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Две entities образуют цикл. Определите владельца связи и варианты развязки."},
{"id":"architecture-fsd:feature-overuse","topic":"architecture-fsd","tab":"advanced","ordinal":5,"targetLevel":"middle","angles":["engineering","nuance"],"kind":"case","title":"Почему 'всё в features' делает проект менее понятным?","shortAnswer":"Слои теряют смысл, а локальный код превращается в множество искусственных API.","explanation":"Выделение требует устойчивого сценария или пользы повторного использования. Page может владеть своей логикой, если это точная граница.","assessment":{"basic":"Распознаёт механическое дробление.","confident":"Возвращает cohesion. Слои теряют смысл, а локальный код превращается в множество искусственных API.","deep":"Появляется устойчивый сценарий и ответственность, которые могут оправдать отдельную feature."},"followUps":[{"kind":"support","question":"Почему feature для каждого переключателя может мешать?","expected":"Создаёт искусственные API и лишние границы локальной логики."},{"kind":"transfer","question":"Переключатель стал общим бизнес-действием с аудитом. Что изменится?","expected":"Появляется устойчивый сценарий и ответственность, которые могут оправдать отдельную feature."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Каждый переключатель стал feature. Оцените стоимость и критерии укрупнения."},
{"id":"architecture-fsd:config-code","topic":"architecture-fsd","tab":"advanced","ordinal":6,"targetLevel":"senior","angles":["engineering"],"kind":"case","title":"Когда конфигурация превращается в плохо типизированный язык программирования?","shortAnswer":"Когда в ней появляются условия, зависимости и скрытые вычисления без проверяемой модели.","explanation":"Декларативность полезна для стабильных вариаций. Сложное поведение часто яснее выразить кодом со стратегиями и тестами.","assessment":{"basic":"Находит сложность DSL.","confident":"Сравнивает config/code. Когда в ней появляются условия, зависимости и скрытые вычисления без проверяемой модели.","deep":"Явная схема/язык, валидация и ограничения исполнения с тестируемыми правилами."},"followUps":[{"kind":"support","question":"Когда конфигурация перестаёт быть простыми данными?","expected":"Когда содержит сложные условия, зависимости и вычисления."},{"kind":"transfer","question":"Пользователь редактирует такую конфигурацию. Как обеспечить предсказуемость?","expected":"Явная схема/язык, валидация и ограничения исполнения с тестируемыми правилами."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Конфигурация содержит условия и вычисления. Определите необходимость модели поведения."},
{"id":"architecture-fsd:microfrontend-state","topic":"architecture-fsd","tab":"advanced","ordinal":7,"targetLevel":"senior","angles":["engineering"],"kind":"case","title":"Как согласовать состояние между микрофронтендами без общего store?","shortAnswer":"Определить минимальный протокол событий/контрактов и владельца каждого факта.","explanation":"Общий глобальный store связывает независимые релизы. Передавать все внутренние actions через шину столь же хрупко.","assessment":{"basic":"Выделяет ownership.","confident":"Проектирует минимальный протокол. Определить минимальный протокол событий/контрактов и владельца каждого факта.","deep":"Дедупликацию, версии и восстановление состояния; транспорт событий сам не гарантирует согласованность."},"followUps":[{"kind":"support","question":"Нужен ли каждому микрофронтенду доступ ко всему чужому store?","expected":"Нет; минимальный протокол и владельцы фактов."},{"kind":"transfer","question":"Одно событие доставлено дважды и не по порядку. Что должен выдержать протокол?","expected":"Дедупликацию, версии и восстановление состояния; транспорт событий сам не гарантирует согласованность."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Микрофронтенды делят данные пользователя. Спроектируйте владельца и минимальный протокол."},
{"id":"architecture-fsd:backend-types","topic":"architecture-fsd","tab":"advanced","ordinal":8,"targetLevel":"senior","angles":["engineering","nuance"],"kind":"case","title":"Почему общий тип backend/frontend не всегда единая модель?","shortAnswer":"Он может описывать транспорт, тогда как UI и домен имеют другие инварианты.","explanation":"Генерация снижает ручные ошибки, но не заменяет mapping и runtime-validation. Совместимость должна учитывать независимые релизы.","assessment":{"basic":"Различает DTO/domain.","confident":"Использует генерацию осмысленно. Он может описывать транспорт, тогда как UI и домен имеют другие инварианты.","deep":"На явной границе с проверкой и доменным решением, не размазывая non-null assertion по экрану."},"followUps":[{"kind":"support","question":"Гарантируют ли сгенерированные типы отсутствие неверного ответа?","expected":"Нет; они описывают заявленный контракт, не проверяют runtime."},{"kind":"transfer","question":"Backend меняет nullable-поле, а UI требует значение. Где адаптировать?","expected":"На явной границе с проверкой и доменным решением, не размазывая non-null assertion по экрану."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Backend-типы предлагают использовать во всём UI. Оцените границы транспорта и инвариантов."},
{"id":"architecture-fsd:optimistic-architecture","topic":"architecture-fsd","tab":"advanced","ordinal":9,"targetLevel":"senior","angles":["engineering"],"kind":"case","title":"Кто должен владеть optimistic update, если сущность видна в нескольких модулях?","shortAnswer":"Один data-layer/доменный владелец с явным протоколом согласования.","explanation":"Локальные независимые патчи могут расходиться. Выбор rollback, версии и invalidation должен учитывать конкурентность и формы представления.","assessment":{"basic":"Находит единый ownership.","confident":"Проектирует reconciliation. Один data-layer/доменный владелец с явным протоколом согласования.","deep":"Единый порядок/версии и reconciliation всех источников, а не отдельный patch каждого UI."},"followUps":[{"kind":"support","question":"Чем опасны два независимых optimistic-владельца одной записи?","expected":"Откаты и подтверждения могут конфликтовать."},{"kind":"transfer","question":"Операции приходят также из realtime-канала. Что добавить?","expected":"Единый порядок/версии и reconciliation всех источников, а не отдельный patch каждого UI."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Экраны оптимистично меняют одну сущность. Определите единого владельца согласования."},
{"id":"architecture-fsd:frontend-transaction","topic":"architecture-fsd","tab":"advanced","ordinal":10,"targetLevel":"senior","angles":["engineering","nuance"],"kind":"case","title":"Можно ли обеспечить транзакцию нескольких backend-вызовов только frontend-кодом?","shortAnswer":"Нет общей атомарности без серверного протокола; клиент может лишь оркестрировать и компенсировать.","explanation":"Сбой между запросами оставляет частичный эффект. Нужны server transaction, saga-подобный протокол или явный UX частичного результата.","assessment":{"basic":"Видит границу атомарности.","confident":"Предлагает серверную координацию. Нет общей атомарности без серверного протокола; клиент может лишь оркестрировать и компенсировать.","deep":"Компенсация либо явное частично завершённое состояние и восстановление, не обещание полного rollback."},"followUps":[{"kind":"support","question":"Может ли клиент сделать два разных HTTP-запроса атомарными сам?","expected":"Нет без серверного протокола."},{"kind":"transfer","question":"Первый шаг необратим, второй упал. Какой контракт нужен?","expected":"Компенсация либо явное частично завершённое состояние и восстановление, не обещание полного rollback."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Операция делает два запроса. Оцените атомарность и частичный отказ."},
{"id":"architecture-fsd:capability-boundary","topic":"architecture-fsd","tab":"advanced","ordinal":11,"targetLevel":"senior","angles":["engineering"],"kind":"case","title":"Как безопасно встраивать сторонний модуль с расширениями?","shortAnswer":"Выдать минимальные возможности через явный API и выбрать настоящую границу изоляции по доверию.","explanation":"TypeScript-интерфейс не изолирует исполняемый код в одном origin. Недоверенный JS требует иной sandbox-границы, чем обычный пакет команды.","assessment":{"basic":"Разделяет contract/isolation.","confident":"Ограничивает capabilities. Выдать минимальные возможности через явный API и выбрать настоящую границу изоляции по доверию.","deep":"Нет в нужном смысле; выбрать настоящую границу изоляции и минимальный протокол доступа."},"followUps":[{"kind":"support","question":"Ограничивает ли TypeScript-интерфейс недоверенный JS во время исполнения?","expected":"Нет; это не runtime-изоляция."},{"kind":"transfer","question":"Плагин получил доступ к глобальному window. Сохранилась ли минимальная capability-модель?","expected":"Нет в нужном смысле; выбрать настоящую границу изоляции и минимальный протокол доступа."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"В приложение встраивается плагин. Определите возможности и реальную изоляцию по доверию."},
{"id":"architecture-fsd:schema-evolution","topic":"architecture-fsd","tab":"advanced","ordinal":12,"targetLevel":"senior","angles":["engineering"],"kind":"case","title":"Как менять persisted клиентский формат без потери данных?","shortAnswer":"Версия, проверяемые миграции, сохранение исходника при неизвестном формате и явная очистка.","explanation":"Автоматическая запись пустого state после неудачного чтения уничтожает шанс восстановления. Миграция должна быть детерминированной и повторяемой.","assessment":{"basic":"Защищает исходник.","confident":"Тестирует migration chain. Версия, проверяемые миграции, сохранение исходника при неизвестном формате и явная очистка.","deep":"Атомарная замена/версионированная запись и проверка результата с сохранением предыдущей версии."},"followUps":[{"kind":"support","question":"Можно ли молча перезаписать неизвестную будущую версию сохранения?","expected":"Не следует; сохранить исходник и определить восстановление."},{"kind":"transfer","question":"Миграция оборвалась посередине записи. Как обеспечить целостность?","expected":"Атомарная замена/версионированная запись и проверка результата с сохранением предыдущей версии."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Формат сохранения меняется. Спроектируйте версию, миграцию и обработку неизвестного формата."},
{"id":"architecture-fsd:architecture-reversal","topic":"architecture-fsd","tab":"advanced","ordinal":13,"targetLevel":"senior","angles":["engineering"],"kind":"case","title":"Как понять, что выбранную абстракцию пора удалить?","shortAnswer":"Когда она не скрывает вариативность, усложняет изменения и не имеет ожидаемых потребителей.","explanation":"Удаление слоя может улучшить архитектуру. Сравнить реальные сценарии, стоимость тестов и ответственность, а не защищать первоначальный план.","assessment":{"basic":"Проверяет фактическую пользу.","confident":"Предлагает упрощение. Когда она не скрывает вариативность, усложняет изменения и не имеет ожидаемых потребителей.","deep":"Совместимый переход, инвентаризация потребителей и deprecation вместо одномоментного удаления."},"followUps":[{"kind":"support","question":"Какой признак говорит, что абстракция не окупается?","expected":"Она не скрывает реальную вариативность и удорожает изменения."},{"kind":"transfer","question":"Абстракцию уже используют внешние команды. Как убрать её безопасно?","expected":"Совместимый переход, инвентаризация потребителей и deprecation вместо одномоментного удаления."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Абстракция усложняет изменения. Предложите критерии удаления и безопасный переход."},
{"id":"architecture-fsd:org-boundaries","topic":"architecture-fsd","tab":"advanced","ordinal":14,"targetLevel":"senior","angles":["engineering","nuance"],"kind":"case","title":"Должна ли структура frontend точно повторять команды?","shortAnswer":"Нет; команды влияют на ownership, но границы должны поддерживать связность продукта и изменения.","explanation":"Организационные границы меняются. Нужно избегать синхронной координации для каждого малого изменения, не дублируя всю систему.","assessment":{"basic":"Учитывает команды.","confident":"Сохраняет доменный смысл. Нет; команды влияют на ownership, но границы должны поддерживать связность продукта и изменения.","deep":"Общего владельца/контракт и координацию изменений, а не просто разделить папки по названиям команд."},"followUps":[{"kind":"support","question":"Должна ли смена оргструктуры автоматически менять доменную модель?","expected":"Нет; ownership и смысловые границы связаны, но не тождественны."},{"kind":"transfer","question":"Две команды регулярно изменяют один инвариант. Что пересмотреть?","expected":"Общего владельца/контракт и координацию изменений, а не просто разделить папки по названиям команд."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Модули предлагают разделить по оргструктуре. Оцените ownership и связность продукта."},
{"id":"architecture-fsd:architecture-proof","topic":"architecture-fsd","tab":"advanced","ordinal":15,"targetLevel":"senior","angles":["nuance"],"kind":"question","title":"Можно ли доказать качество архитектуры прохождением lint-правил?","shortAnswer":"Нет; правила подтверждают отдельные синтаксические инварианты, а не пригодность продукта к изменениям.","explanation":"Нужны реальные сценарии эволюции, эксплуатационные данные и review модели. Зелёный граф может скрывать неправильные границы смысла.","assessment":{"basic":"Знает предел автоматики.","confident":"Проверяет change scenarios. Нет; правила подтверждают отдельные синтаксические инварианты, а не пригодность продукта к изменениям.","deep":"Сравнить обнаруженные нарушения, время обратной связи и стоимость сопровождения; автоматизация должна защищать конкретные повторяющиеся риски."},"followUps":[{"kind":"support","question":"Что действительно доказывает зелёный линтер импортов?","expected":"Соблюдение проверяемых синтаксических правил."},{"kind":"transfer","question":"Линтер выключили, но команда сохраняет те же правила вручную. Как проверить пользу автоматизации?","expected":"Сравнить обнаруженные нарушения, время обратной связи и стоимость сопровождения; автоматизация должна защищать конкретные повторяющиеся риски."}],"context":"Feature-Sliced Design: актуальная документация, layers/slices/segments. Архитектурные решения зависят от продукта; приведены условия и компромиссы, а не универсальные запреты.","references":["https://feature-sliced.design/docs/reference/layers","https://feature-sliced.design/docs/reference/slices-segments","https://feature-sliced.design/docs/reference/public-api","https://martinfowler.com/articles/micro-frontends.html"],"verifiedAt":"2026-11-13","question":"Линтер импортов зелёный. Объясните границы доказательства и проверку пригодности архитектуры."}
);
